tool_input.command:
$v3 = 'D:\repository\苏州市房地产监测V3\zhi2-web-admin'
$target = 'D:\repository\苏住房G\worktrees\task2468-navbar-visual\zhi2-web-admin'
$sourceFiles = @(
  @{ Source = "$v3\public\assets\images\navbar-bg.png"; Destination = "$target\public\assets\images\navbar-bg.png" },
  @{ Source = "$v3\src\utils\menuPlatformIcons.js"; Destination = "$target\src\utils\menuPlatformIcons.js" },
  @{ Source = "$v3\src\layout\components\navbarMenuIcons.generated.html"; Destination = "$target\src\layout\components\navbarMenuIcons.generated.html" },
  @{ Source = "$v3\scripts\generate-navbar-menu-icons.mjs"; Destination = "$target\scripts\generate-navbar-menu-icons.mjs" }
)
foreach ($file in $sourceFiles) {
  if (-not (Test-Path -LiteralPath $file.Source)) { throw "Missing source: $($file.Source)" }
  if (Test-Path -LiteralPath $file.Destination) { throw "Target already exists: $($file.Destination)" }
}
$sourceIcons = "$v3\public\assets\images\menu-icons"
$targetIcons = "$target\public\assets\images\menu-icons"
if (-not (Test-Path -LiteralPath $sourceIcons)) { throw "Missing source: $sourceIcons" }
if (Test-Path -LiteralPath $targetIcons) { throw "Target already exists: $targetIcons" }
foreach ($file in $sourceFiles) { Copy-Item -LiteralPath $file.Source -Destination $file.Destination }
Copy-Item -LiteralPath $sourceIcons -Destination $targetIcons -Recurse
(Get-ChildItem -LiteralPath $targetIcons -File -Recurse | Measure-Object).Count
